import{_ as s,o as n,c as p,a5 as t}from"./chunks/framework.bIR-4glx.js";const u=JSON.parse('{"title":"创业实验卡：在两周内记录假设、证据、成本和继续或停止的决定","description":"可复制的创业实验记录，包含问题、用户、替代方案、反证条件、人工试点、投入上限和事后判读，并用完整假设案例示范如何得出有限结论。","frontmatter":{"title":"创业实验卡：在两周内记录假设、证据、成本和继续或停止的决定","description":"可复制的创业实验记录，包含问题、用户、替代方案、反证条件、人工试点、投入上限和事后判读，并用完整假设案例示范如何得出有限结论。","updated":"2026-09-19T00:00:00.000Z","worksheetDownload":{"url":"/downloads/worksheets/startup-experiment.zh.md","name":"startup-experiment.zh.md"}},"headers":[],"relativePath":"templates/startup-experiment.md","filePath":"templates/startup-experiment.md","lastUpdated":1789776000000}'),e={name:"templates/startup-experiment.md"};function l(d,a,r,i,c,o){return n(),p("div",null,[...a[0]||(a[0]=[t(`<h1 id="创业实验卡" tabindex="-1">创业实验卡 <a class="header-anchor" href="#创业实验卡" aria-label="Permalink to &quot;创业实验卡&quot;">​</a></h1><p>用于回答一个具体问题：“下一步投入是否值得？”先填写假设、范围和判定条件，再接触用户。以下是本指南建议的工作模板，不是市场验证标准；两周是可调整的期限，示例全部为假设。</p><p>一次只检验一个主要假设。出现超出范围的新问题时，记录下来，不把同一张卡悄悄扩成完整创业计划。背景方法见 <a href="./../threads/practice/customer-discovery">从真实问题到首批用户</a>；工时和经营观察见 <a href="./../threads/practice/sustainable-business">可持续的小生意</a>。</p><h2 id="复制空白卡" tabindex="-1">复制空白卡 <a class="header-anchor" href="#复制空白卡" aria-label="Permalink to &quot;复制空白卡&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>实验名称 / 编号：</span></span>
<span class="line"><span>负责人 / 起止日期：</span></span>
<span class="line"><span>要支持的下一步决定：</span></span>
<span class="line"><span></span></span>
<span class="line"><span>【实验开始前填写】</span></span>
<span class="line"><span>目标用户与具体任务：</span></span>
<span class="line"><span>使用者 / 决策者 / 付款者：</span></span>
<span class="line"><span>任务最近发生的证据：</span></span>
<span class="line"><span>当前替代方案及其代价：</span></span>
<span class="line"><span>主要假设（可能被推翻的一句话）：</span></span>
<span class="line"><span>最强的反例或其他解释：</span></span>
<span class="line"><span></span></span>
<span class="line"><span>接触渠道 / 纳入条件：</span></span>
<span class="line"><span>计划邀请数 / 计划访谈数 / 计划试点数：</span></span>
<span class="line"><span>招募可能造成的偏差（例如熟人或主动报名）：</span></span>
<span class="line"><span>试点交付物 / 明确不包含的事项：</span></span>
<span class="line"><span>报价 / 修改范围 / 交付与验收方式：</span></span>
<span class="line"><span>人工和工具各做什么：</span></span>
<span class="line"><span>材料授权 / 记录同意 / 保存与删除安排：</span></span>
<span class="line"><span></span></span>
<span class="line"><span>旧流程基线（质量、双方耗时、支出）：</span></span>
<span class="line"><span>要记录的行为证据及记录位置：</span></span>
<span class="line"><span>继续的预定条件：</span></span>
<span class="line"><span>调整的预定条件：</span></span>
<span class="line"><span>停止或暂缓的预定条件：</span></span>
<span class="line"><span>工时上限 / 现金支出上限 / 截止日期：</span></span>
<span class="line"><span>谁有权停止 / 如何处理未完成承诺：</span></span>
<span class="line"><span></span></span>
<span class="line"><span>【实验结束后填写】</span></span>
<span class="line"><span>实际邀请 / 回应 / 访谈 / 报价 / 付费 / 验收数量：</span></span>
<span class="line"><span>真实用户行为（匿名编号 + 日期 + 证据摘要）：</span></span>
<span class="line"><span>反例 / 拒绝理由 / 中途退出及原因：</span></span>
<span class="line"><span>实际报价 / 到账 / 退款 / 支出：</span></span>
<span class="line"><span>全部工时（招募、沟通、准备、制作、修改、支持）：</span></span>
<span class="line"><span>新旧流程比较及仍不可比的条件：</span></span>
<span class="line"><span>偏离原计划的事项和原因：</span></span>
<span class="line"><span></span></span>
<span class="line"><span>支持了什么 / 没有支持什么：</span></span>
<span class="line"><span>决定：继续 / 调整 / 停止 / 证据不足，暂缓</span></span>
<span class="line"><span>决定依据：</span></span>
<span class="line"><span>尚未完成的承诺及处理人：</span></span>
<span class="line"><span>下一轮只改变什么：</span></span>
<span class="line"><span>什么新事实会改变本轮判断：</span></span>
<span class="line"><span>下次复盘日期：</span></span></code></pre></div><p>不必把每格写成长文。证据摘要可以写成“用户 A 展示上周两次任务的去标识样例”，不要把完整客户材料贴进公共仓库。收款记录只保留验证所需的匿名摘要，私人联系方式和交易凭据留在适当的受限位置。</p><h2 id="填写示例-商品资料整理试点" tabindex="-1">填写示例：商品资料整理试点 <a class="header-anchor" href="#填写示例-商品资料整理试点" aria-label="Permalink to &quot;填写示例：商品资料整理试点&quot;">​</a></h2><p>这个例子只测试“小店经营者是否愿意为限定范围的资料整理付费，并能否按限定工时交付”，不是 AI 产品发布计划。所有人物、行为和数字均为虚构演示。</p><table tabindex="0"><thead><tr><th>字段</th><th>示例填写</th></tr></thead><tbody><tr><td>期限与负责人</td><td>两周，由试点负责人记录并作决定</td></tr><tr><td>用户与任务</td><td>自己维护商品信息、最近两周至少更新过两批资料的小店经营者</td></tr><tr><td>角色</td><td>经营者本人使用、决定并付款；只纳入这种情况</td></tr><tr><td>当前办法</td><td>用已有表格逐项复制，再人工核对规格</td></tr><tr><td>主要假设</td><td>有人愿付 200 元，请人将最多 20 条已确认商品信息整理为一份待发布草稿</td></tr><tr><td>反例</td><td>现有模板已经够快，购买服务增加的沟通时间反而更多</td></tr><tr><td>招募与偏差</td><td>邀请 10 人，目标访谈 6 人；含熟人，结果不能直接代表陌生客户</td></tr><tr><td>试点范围</td><td>最多 2 单；一份草稿和待确认项，包含一轮范围内修改；不代发布，不新增商品事实</td></tr><tr><td>材料与说明</td><td>只使用经营者确认可用的资料；告知人工整理和工具辅助方式，未经许可不外传</td></tr><tr><td>验收</td><td>20 条以内约定字段齐全，待确认项可识别，由客户核对后确认接收</td></tr><tr><td>投入上限</td><td>全轮 12 小时、现金支出 100 元；这些数字只是本例选择</td></tr><tr><td>继续条件</td><td>6 次访谈中至少 3 人有近期重复任务；至少 2 人按 200 元付费、完成验收，且每单沟通至支持不超过 2 小时</td></tr><tr><td>调整条件</td><td>有付款并验收，但单次工时超限；下一轮缩小范围或改善输入要求</td></tr><tr><td>停止或暂缓</td><td>截止日期内未获得足够证据、触及总投入上限，或无法获得必要资料使用许可</td></tr></tbody></table><p>基线也要落到一项任务上：假设两名试点用户各自提供了旧流程计时摘要，分别为 90 和 60 分钟。新流程中，用户侧准备、沟通和审核分别花了 30 和 70 分钟，服务方则用了 90 和 210 分钟。这里有用户节省时间的信号，也有用户时间增加的反例；不能只展示第一位用户。</p><h2 id="示例结果与判读" tabindex="-1">示例结果与判读 <a class="header-anchor" href="#示例结果与判读" aria-label="Permalink to &quot;示例结果与判读&quot;">​</a></h2><p>假设实际邀请 10 人，8 人回应，6 人完成访谈，其中 4 人展示了近期重复任务。向 3 人发出相同报价，2 人付款并验收，另 1 人因现有模板够用而拒绝。共到账 400 元、没有退款、现金支出 40 元，包含所有招募与交付工作共 11 小时。其中两单服务方工时为 1.5 与 3.5 小时，其他工作为 6 小时，合计仍是 11 小时。</p><p>第二单材料格式不一致，产生了额外核对；用户自己的准备和审核时间也超过旧流程。虽然付费与验收数量满足约定，单次工时条件没有满足，因此本轮决定是<strong>调整</strong>。下一轮只接收符合输入模板的资料，保持价格和数量上限不变，再检验工时。这个选择仍是待验证假设，不能先写成已解决的问题。</p><p>本轮支持“这两位用户在这些条件下接受了付费试点”，没有证明常规复购、陌生渠道获客成本或可持续利润。<code>400 - 40 = 360 元</code> 只是扣除所列现金支出的余额，没有计入 11 小时劳动及其他成本；不能写成赚了 360 元。</p><p>如果本轮仅访谈 2 人，应记录“未达到预定证据量，暂缓判断”，并说明是招募困难还是投入不足。不要在看完结果后把门槛降为 2 人，再宣称达标。确需改计划时保留原版本、变更时间和原因，把新条件用于下一轮。</p><h2 id="最后写一句能被复查的结论" tabindex="-1">最后写一句能被复查的结论 <a class="header-anchor" href="#最后写一句能被复查的结论" aria-label="Permalink to &quot;最后写一句能被复查的结论&quot;">​</a></h2><blockquote><p>在两周、12 小时和 100 元支出上限内，我们观察到 2 次付费并验收，但 1 单超出交付工时上限。我们将缩小可接受的材料格式，再做一轮；目前不扩大接单量。</p></blockquote><p>需要英语汇报时：</p><blockquote><p>Two customers paid for and accepted the pilot, but one delivery exceeded our time limit. We will test a stricter input format before taking more orders. Repeat demand and sustainable costs remain unproven.</p></blockquote>`,19)])])}const m=s(e,[["render",l]]);export{u as __pageData,m as default};
